<script lang="ts">let { columns = [], rows = [] }: { columns: { key: string; label: string; sortable?: boolean }[]; rows: Record<string, unknown>[] } = $props();let sortKey = $state('');let sortDir = $state<1 | -1>(1);let sorted = $derived.by(() => { if (!sortKey) return rows; return [...rows].sort((a, b) => { const av = a[sortKey]; const bv = b[sortKey]; if (av === bv) return 0; return ((av as string) > (bv as string) ? 1 : -1) * sortDir; }); });function toggle(k: string) { if (sortKey === k) sortDir = sortDir === 1 ? -1 : 1; else { sortKey = k; sortDir = 1; } }</script><table><thead><tr>{#each columns as c}<th aria-sort={sortKey === c.key ? (sortDir === 1 ? 'ascending' : 'descending') : 'none'}>{#if c.sortable}<button onclick={() => toggle(c.key)}>{c.label} {sortKey === c.key ? (sortDir === 1 ? '▲' : '▼') : ''}</button>{:else}{c.label}{/if}</th>{/each}</tr></thead><tbody>{#each sorted as r}<tr>{#each columns as c}<td>{String(r[c.key] ?? '')}</td>{/each}</tr>{/each}</tbody></table><style>table{width:100%;border-collapse:collapse}th{position:sticky;top:0;background:var(--bg-1);text-align:left;font-size:var(--fs-xs);color:var(--text-2);padding:var(--space-2) var(--space-3);border-bottom:1px solid var(--border)}th button{background:none;border:none;color:inherit}td{padding:var(--space-2) var(--space-3);border-bottom:1px solid var(--border);font-size:var(--fs-sm)}</style>
